function i_h($s) { return htmlspecialchars((string)$s, ENT_QUOTES, 'UTF-8'); }
function i_data_path($root) {
    $p = '';
    foreach ([$root . '/core/datapath.php', $root . '/data/datapath.php'] as $f) { if ($p === '' && is_file($f)) { $x = @include $f; if (is_string($x) && $x !== '' && is_dir($x)) $p = $x; } }
    return rtrim(str_replace('\\', '/', $p ?: ($root . '/data')), '/') . '/';
}
