function i_post($k, $d = '') { return isset($_POST[$k]) && is_string($_POST[$k]) ? trim($_POST[$k]) : $d; }
function i_check_csrf($csrf) { return isset($_POST['_token']) && is_string($_POST['_token']) && hash_equals($csrf, $_POST['_token']); }
function i_url() { $https = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') || (isset($_SERVER['HTTP_X_FORWARDED_PROTO']) && strtolower($_SERVER['HTTP_X_FORWARDED_PROTO']) === 'https'); $host = isset($_SERVER['HTTP_HOST']) ? $_SERVER['HTTP_HOST'] : 'localhost'; $path = rtrim(str_replace('\\','/', dirname(isset($_SERVER['SCRIPT_NAME']) ? $_SERVER['SCRIPT_NAME'] : '/')), '/'); return ($https ? 'https://' : 'http://') . $host . ($path === '/' ? '' : $path); }
function i_protect($dir) { if (!is_dir($dir)) @mkdir($dir, 0750, true); @file_put_contents($dir . '/.htaccess', "# Apache 2.2/2.4\n<IfModule mod_authz_core.c>Require all denied</IfModule>\n<IfModule !mod_authz_core.c>Order allow,deny\nDeny from all</IfModule>\n"); @file_put_contents($dir . '/web.config', "<?xml version=\"1.0\" encoding=\"UTF-8\"?><configuration><system.webServer><security><requestFiltering><fileExtensions allowUnlisted=\"false\" /></requestFiltering></security></system.webServer></configuration>"); @file_put_contents($dir . '/index.html', ''); }
function i_split_sql($sql) { $out=[]; $buf=''; $quote=''; $len=strlen($sql); for($i=0;$i<$len;$i++){ $c=$sql[$i]; if($quote){$buf.=$c; if($c===$quote && ($i===0 || $sql[$i-1] !== '\\')) $quote='';} else { if($c==='\'' || $c==='"' || $c==='`'){$quote=$c;$buf.=$c;} elseif($c===';'){if(trim($buf)!=='')$out[]=trim($buf);$buf='';} else $buf.=$c; } } if(trim($buf)!=='')$out[]=trim($buf); return $out; }
function i_checks($root, $data) { $checks=[]; $checks[]=['PHP 版本 ≥ 7.0',PHP_VERSION_ID>=70000,PHP_VERSION]; foreach(['pdo_mysql','openssl','curl','json'] as $e)$checks[]=['PHP 扩展 '.$e,extension_loaded($e),extension_loaded($e)?'已安装':'请在宝塔「PHP 设置 → 安装扩展」或 php.ini 中启用（Windows/IIS：extension=php_xxx.dll）']; $checks[]=['mbstring（可选）',extension_loaded('mbstring'),extension_loaded('mbstring')?'已安装':'未安装，将使用内置兼容处理']; $ok=is_dir($data)?is_writable($data):is_writable(dirname($data)); $checks[]=['data 目录可写',$ok,$ok?'可写（无需 777）':'宝塔请将目录所有者设为 www；IIS 请给 IIS_IUSRS 修改权限']; $https=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')||(isset($_SERVER['HTTP_X_FORWARDED_PROTO'])&&strtolower($_SERVER['HTTP_X_FORWARDED_PROTO'])==='https'); $checks[]=['HTTPS',$https,$https?'已启用':'建议启用 HTTPS（安装器仍可继续）']; return $checks; }
