    $host=i_post('db_host','127.0.0.1'); $port=(int)i_post('db_port','3306'); $name=i_post('db_name'); $user=i_post('db_user'); $pass=isset($_POST['db_pass'])?(string)$_POST['db_pass']:''; $prefix=i_post('db_prefix','idc_');
    if(!preg_match('/^[A-Za-z0-9_]*$/',$prefix)) throw new Exception('表前缀只能包含字母、数字、下划线'); if(!preg_match('/^[A-Za-z0-9_$-]+$/',$name)) throw new Exception('数据库名格式不正确');
    $dsn='mysql:host='.$host.';port='.$port.';charset=utf8mb4'; $pdo=new PDO($dsn,$user,$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
    if(!empty($_POST['create_db'])) {$pdo->exec('CREATE DATABASE IF NOT EXISTS `'.str_replace('`','``',$name).'` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci');}
    $pdo=new PDO($dsn.';dbname='.$name,$user,$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
    $site=i_post('site_name','o2o云'); $siteUrl=rtrim(i_post('site_url',i_url()),'/'); $admin=i_post('admin_user','admin'); $email=i_post('admin_email'); $apass=isset($_POST['admin_pass'])?(string)$_POST['admin_pass']:''; $apass2=isset($_POST['admin_pass2'])?(string)$_POST['admin_pass2']:''; if($site==='')throw new Exception('请填写站点名称'); if(!preg_match('/^[A-Za-z0-9_\-]{2,50}$/',$admin))throw new Exception('管理员用户名仅支持 2-50 位字母、数字、下划线、短横线'); if(strlen($apass)<8||$apass!==$apass2)throw new Exception('管理员密码至少 8 位且两次输入必须一致'); if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new Exception('管理员邮箱格式不正确');
    if(!is_dir($data)&&!@mkdir($data,0700,true))throw new Exception('无法创建 data 目录，请检查权限'); if(!is_writable($data))throw new Exception('data 目录不可写：宝塔请授权 www 用户，IIS 请授权 IIS_IUSRS 修改权限'); $mode=i_post('data_mode','random'); if($mode==='custom'){ $cp=rtrim(str_replace('\\','/',i_post('data_path')),'/'); if($cp===''||!preg_match('#^(/|[A-Za-z]:/)#',$cp)) throw new Exception('自定义数据目录必须是绝对路径'); if(!is_dir($cp)&&!@mkdir($cp,0750,true)) throw new Exception('无法创建数据目录 '.$cp.'（检查权限或 open_basedir）'); if(!is_writable($cp)) throw new Exception('数据目录不可写：'.$cp); $data=$cp.'/'; } elseif($mode==='random'){ $rd=$root.'/data_'.bin2hex(random_bytes(8)); if(@mkdir($rd,0750,true)) $data=$rd.'/'; } if(rtrim($data,'/')!==rtrim($root.'/data','/')){ if(@file_put_contents($root.'/data/datapath.php',"<?php\nreturn ".var_export(rtrim($data,'/'),true).";\n",LOCK_EX)===false) throw new Exception('无法写入 data/datapath.php'); @chmod($root.'/data/datapath.php',0640); }
