    $cfg=['database'=>['type'=>'mysql','hostname'=>$host,'database'=>$name,'username'=>$user,'password'=>$pass,'hostport'=>(string)$port,'charset'=>'utf8mb4','prefix'=>$prefix],'app_key'=>bin2hex(random_bytes(32)),'debug'=>false,'timezone'=>'Asia/Shanghai']; $php="<?php\nreturn ".var_export($cfg,true).";\n"; if(@file_put_contents($data.'config.php',$php,LOCK_EX)===false)throw new Exception('写入 data/config.php 失败'); @chmod($data.'config.php',0600); if(@file_put_contents($data.'install.lock.php',"<?php exit;\n// installed ".date('c')."\n",LOCK_EX)===false)throw new Exception('写入安装锁失败'); @chmod($data.'install.lock.php',0600); $done=true;
  } catch(Exception $e){$err=$e->getMessage();} }
if($done){$body='<div class="card p-4"><h1 class="text-success">安装完成</h1><p>站点已初始化，后台地址：<a href="'.i_h($siteUrl.'/admin').'">'.i_h($siteUrl.'/admin').'</a></p><div class="alert alert-warning">请立即删除或锁定网站根目录的 install.php，并确认 data/core 已被 Web 服务器禁止访问。</div><h5>计划任务</h5><pre class="mono">宝塔/Linux：php '.i_h($root).'/cron.php\n无 CLI 主机：'.$siteUrl.'/index.php?s=/api/cron/run&amp;key='.i_h($settings['cron_key']).'\nWindows：任务计划程序执行 php.exe '.i_h($root.'/cron.php').'</pre><p>安装器已写入 data/config.php、data/install.lock.php 与运行目录保护文件。</p></div>'; i_page('安装完成',$body,$csrf); exit; }
$body='<div class="card p-4"><h1 class="h3">欢迎安装 o2o云</h1><p class="text-muted">PHP 7.0+ · MySQL 5.6/5.7/8.0 · MariaDB；utf8mb4 下索引已按 varchar(191) 兼容旧版 MySQL。</p>'.($err?'<div class="alert alert-danger">'.i_h($err).'</div>':'').'<h4>1. 环境检测</h4><table class="table table-sm">'; foreach($checks as $c)$body.='<tr><td>'.i_h($c[0]).'</td><td>'.($c[1]?'<span class="text-success">通过</span>':'<span class="text-danger">未通过</span>').'</td><td>'.i_h($c[2]).'</td></tr>'; $body.='</table><form method="post" autocomplete="off"><input type="hidden" name="_token" value="'.i_h($csrf).'"><h4>2. 数据库配置</h4><div class="row g-2"><div class="col-md-6"><label>主机</label><input class="form-control" name="db_host" value="'.i_h(i_post('db_host','127.0.0.1')).'"></div><div class="col-md-3"><label>端口</label><input class="form-control" name="db_port" value="'.i_h(i_post('db_port','3306')).'"></div><div class="col-md-3"><label>表前缀</label><input class="form-control" name="db_prefix" value="'.i_h(i_post('db_prefix','idc_')).'"></div><div class="col-md-6"><label>数据库名</label><input class="form-control" name="db_name" required value="'.i_h(i_post('db_name')).'"></div><div class="col-md-6"><label>用户名</label><input class="form-control" name="db_user" required value="'.i_h(i_post('db_user')).'"></div><div class="col-md-6"><label>密码</label><input class="form-control" type="password" name="db_pass"></div><div class="col-md-6 align-self-end"><label><input type="checkbox" name="create_db" value="1"> 自动创建数据库（需 CREATE 权限）</label></div></div><h4 class="mt-4">3. 站点与管理员</h4><div class="row g-2"><div class="col-md-6"><label>站点名称</label><input class="form-control" name="site_name" value="'.i_h(i_post('site_name','o2o云')).'"></div><div class="col-md-6"><label>站点 URL</label><input class="form-control" name="site_url" value="'.i_h(i_post('site_url',i_url())).'"></div><div class="col-md-4"><label>管理员用户名</label><input class="form-control" name="admin_user" value="'.i_h(i_post('admin_user','admin')).'"></div><div class="col-md-4"><label>管理员邮箱</label><input class="form-control" type="email" name="admin_email" required value="'.i_h(i_post('admin_email')).'"></div><div class="col-md-4"><label>后台入口</label><input class="form-control" value="admin" disabled><small class="text-muted">当前版本固定为 admin</small></div><div class="col-md-6"><label>密码（至少 8 位）</label><input class="form-control" type="password" name="admin_pass" required></div><div class="col-md-6"><label>确认密码</label><input class="form-control" type="password" name="admin_pass2" required></div><div class="col-12"><label class="form-label">数据目录（保存配置、缓存、日志）</label><select class="form-select" name="data_mode" onchange="document.getElementById(\'dp\').style.display=this.value===\'custom\'?\'block\':\'none\'"><option value="random" selected>网站内随机名目录 data_xxxxxxxx（推荐，虚拟主机/Apache 不支持 .htaccess 时也安全）</option><option value="custom">自定义绝对路径（推荐放在网站根目录之外，如 /www/idc_data）</option><option value="default">网站根目录下的 data（依赖 .htaccess / web.config / Nginx 规则保护）</option></select><input id="dp" style="display:none" class="form-control mt-2" name="data_path" placeholder="/www/wwwroot/idc_data 或 D:/idc_data"><div class="form-text">数据目录只需对 PHP 运行用户可写，无需 777。</div></div></div><button class="btn btn-primary mt-4" type="submit"'.($fatal?' disabled':'').'>开始安装</button></form><hr><p class="small text-muted">宝塔：网站目录权限建议 755、所有者 www，不要使用 777；IIS：给 IIS_IUSRS 对 data 目录授予修改权限。Nginx 请配置 core/data deny 规则。</p></div>'; i_page('安装向导',$body,$csrf);
